const body = $input.first()?.json?.body || $input.first()?.json || {};
const topic = String(body.topic || body.message || body.query || '').trim();
if (!topic) throw new Error('Missing search topic/query.');
const targetAge = body.targetAge || body.age || '';
const query = [
  `主题: ${topic}`,
  targetAge ? `目标年龄: ${targetAge}` : '',
  body.tone ? `语气: ${body.tone}` : '',
  body.goal ? `教育目标: ${body.goal}` : '',
  '需要适合儿童绘本创作的事实、心理支持方法、教育目标和表达边界。'
].filter(Boolean).join('\n');
return [{ json: {
  userId: String(body.userId || 'anonymous'),
  topic,
  category: String(body.category || ''),
  targetAge,
  limit: Math.max(1, Math.min(20, Number(body.limit) || 8)),
  query
} }];

const query = $('Build RAG Query').first().json;
const response = $input.first().json || {};
const vector = response.embedding || response.data?.[0]?.embedding || response.vector;
if (!Array.isArray(vector)) throw new Error('Embedding response did not contain a query vector.');
const must = [];
if (query.category) must.push({ key: 'category', match: { value: query.category } });
const filter = {
  should: [
    { key: 'userId', match: { value: query.userId } },
    { key: 'visibility', match: { value: 'public' } }
  ],
  must
};
return [{ json: {
  vector,
  limit: query.limit,
  with_payload: true,
  with_vector: false,
  filter
} }];

const query = $('Build RAG Query').first().json;
const result = $input.first().json || {};
const matches = Array.isArray(result.result) ? result.result : Array.isArray(result.points) ? result.points : [];
const references = matches.map((match, index) => {
  const payload = match.payload || {};
  return {
    rank: index + 1,
    score: match.score,
    title: payload.title || 'Untitled',
    documentId: payload.documentId || '',
    category: payload.category || '',
    ageRange: payload.ageRange || '',
    text: String(payload.text || '').slice(0, 1200)
  };
});
const context = references.length
  ? references.map((ref) => `【资料${ref.rank}】${ref.title}${ref.ageRange ? `（适用年龄:${ref.ageRange}）` : ''}\n${ref.text}`).join('\n\n')
  : '未检索到可用参考资料。生成时应明确说明参考资料不足，并使用通用儿童绘本创作原则。';
return [{ json: {
  success: true,
  topic: query.topic,
  targetAge: query.targetAge,
  referenceCount: references.length,
  references,
  context
} }];
